       Esto evita que alguien entre al inventario si no está logueado
       o si intenta volver con la flecha del navegador */
          useEffect(() => {

        const auth = localStorage.getItem("auth");
        const usuarioID = localStorage.getItem("usuarioID");
        const nombreGuardado = localStorage.getItem("nombreUsuario");

        if (!usuarioID || !auth) {
                navigate ("/", {replace:true});
            } else {
                setNombreUsuario(nombreGuardado || "Invitado");
            }
}, [navigate]);

        /*  FUNCIÓN PARA CERRAR SESIÓN 
       Elimina la sesión guardada y redirige al login */
       const cerrarSesion = () => {
        localStorage.removeItem("usuarioID");
        localStorage.removeItem("auth");
        localStorage.removeItem("nombreUsuario");
        navigate("/");

    };




            return (
                <section id="Inicio">
                    <div className='TituloInicio'>
                        <h2>{nombreUsuario}, ¡Bienvenido a FOLTEC gestor de inventarios!</h2>
                    </div>
                    <div className='ImagenInicio'>
                        <img src="https://img.freepik.com/premium-vector/warehouse-workers-check-inventory-warehouse_530733-2940.jpg?w=360" alt="Imagen de gestor" />
                    </div>
                </section>
            );

}
